// Native scroll drives all scene transforms. No wheel/touch interception or autoplay.
(()=>{
 const root=document.querySelector('#app'),motionQuery=matchMedia('(prefers-reduced-motion:reduce)');let mounted=false,blocked=false,sandbox=false,originalStorage=null,anchor=null,host=null,frame=null,landing=null,landingShell=null,bar=null,flight=null,raf=0,mode='',chapter=-1,progress=0,range=1,height=1,width=1,bookBox=null,bookID='',lastPaint=0,reduced=false,lastTime=0,ghost=null,ghostAt=0,ghostDir=1;
 const {clampScroll,scrollRange,scrollEase,scrollScene}=window.fixiverseScrollModel;
 const marks=[0,.16,.28,.43,.53,.62,.69,.78,.86,.99];
 const noMotion=()=>reduced||motionQuery.matches;
 function beginSandbox(){if(sandbox)return;sandbox=true;originalStorage=window.fixiverseStorage;window.fixiverseStorage=window.fixiverseJourneyModels.temporaryJourneyStorage(originalStorage);}
 function makeBar(){bar=document.createElement('aside');bar.id='scroll-tour-controls';bar.setAttribute('aria-label','Scroll through Fixiverse');bar.innerHTML=`<div class="scroll-tour-copy"><span id="scroll-tour-kicker">SCROLL TO EXPLORE · TOUR ACTIONS ARE NOT SAVED</span><h2 id="scroll-tour-title"></h2><p id="scroll-tour-description"></p></div><div class="scroll-tour-actions"><button data-scroll-tour="previous" aria-label="Previous scroll chapter">←</button><button data-scroll-tour="next" aria-label="Next scroll chapter">→</button><button data-scroll-tour="motion" aria-pressed="${noMotion()}">${noMotion()?'Motion off':'Reduce motion'}</button><button class="scroll-tour-start" data-scroll-tour="start">Start learning ↗</button><button data-scroll-tour="exit">Skip tour</button></div><label class="scroll-tour-scrubber"><span class="sr-only">Tour position</span><input id="scroll-tour-position" type="range" min="0" max="100" step="1" value="0" aria-label="Tour position"></label>`;document.body.append(bar);}
 function detachLanding(){const item=root.querySelector('.learning-more');if(item){if(landing&&landing!==item)landing.remove();landing=item;if(!landingShell){landingShell=document.createElement('div');landingShell.className='shelf-home scroll-landing';}host.after(landingShell);landingShell.append(landing);}}
 function makeHome(){window.fixiverseHome();detachLanding();}
 function setMode(next,p){if(mode===next)return;const controlFocus=document.activeElement;ghost?.remove();ghost=null;if(mode&&mode!=='home'&&(next!=='home'||mode.endsWith('repair'))){ghost=root.cloneNode(true);ghost.removeAttribute('id');ghost.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));ghost.classList.add('scroll-scene-ghost');ghost.inert=true;ghost.setAttribute('aria-hidden','true');ghost.style.zIndex='2';frame.append(ghost);ghostDir=p>=lastPaint?1:-1;const bounds=[0,.10,.23,.34,.49,.59,.67,.73,.82,.92,1],chapterAt=scrollScene(p).chapter;ghostAt=bounds[chapterAt+(ghostDir<0?1:0)];}mode=next;root.inert=false;root.style.transform='none';root.style.opacity='1';flight?.remove();flight=null;bookID='';bookBox=null;
  if(next==='home')makeHome();else{beginSandbox();if(next.startsWith('fraction'))window.fixiverseFraction.tourScene(next.split('-')[1]);else window.fixiversePatternTour.scene(next.split('-')[1]);root.inert=true;const note=root.querySelector('.save-note');if(note)note.textContent='Scroll tour · use the mission to save your own work';}if(controlFocus&&bar?.contains(controlFocus))controlFocus.focus({preventScroll:true});
 }
 function measure(){if(!mounted)return;width=frame.clientWidth;height=frame.clientHeight;range=height*(width<801?6:7);host.style.height=`${range+height}px`;bookBox=null;}
 function measureBook(id){const book=root.querySelector(id==='fraction'?'.fraction-book':'.pattern-book');if(!book)return null;const camera=root.querySelector('.learning-nook');if(camera)camera.style.transform='none';const b=book.getBoundingClientRect(),f=frame.getBoundingClientRect();return{x:b.left-f.left,y:b.top-f.top,w:b.width,h:b.height};}
 function cameraFor(amount,id='fraction'){const camera=root.querySelector('.learning-nook');if(!camera)return;const b=bookBox||measureBook(id);if(!b)return;const z=noMotion()?0:amount,scale=1+z*(width<801?.12:.3),cx=b.x+b.w/2,cy=b.y+b.h/2,tx=(width*.52-cx)*z*.65,ty=(height*.48-cy)*z*.55;camera.style.transformOrigin=`${cx}px ${cy}px`;camera.style.transform=`translate3d(${tx}px,${ty}px,0) scale(${scale})`;return{x:b.x-b.w*(scale-1)/2+tx,y:b.y-b.h*(scale-1)/2+ty,w:b.w*scale,h:b.h*scale};}
 function makeBook(id){if(flight&&bookID===id)return;flight?.remove();bookID=id;bookBox=mode==='home'?measureBook(id):null;
  flight=document.createElement('div');flight.className=`scroll-flying-book ${id}`;flight.id='scroll-flying-book';flight.setAttribute('aria-hidden','true');flight.innerHTML=`<div class="scroll-book-pages"><div><span>FIXIVERSE / ${id==='fraction'?'01':'02'}</span><b>${id==='fraction'?'One whole.':'Find the loop.'}</b><i>${id==='fraction'?'½':'☀ ❧'}</i></div><div><span>YOUR NEXT CHAPTER</span><b>Your ideas<br>belong here.</b><i>✧</i></div></div><div class="scroll-book-cover"><small>THE CURIOSITY COLLECTION</small><strong>${id==='fraction'?'Fraction<br>Foundry':'Pattern<br>Grove'}</strong><i>${id==='fraction'?'½':'☀ ❧'}</i><span>TRY · NOTICE · REPAIR</span></div>`;frame.append(flight);
 }
 function paintBook(s){root.querySelectorAll('.journey-hidden-book').forEach(e=>e.classList.remove('journey-hidden-book'));if(!s.book||noMotion()){flight?.remove();flight=null;bookID='';return;}makeBook(s.book);const b=bookBox||{x:width*.62,y:height*.38,w:width*.14,h:height*.3};if(mode==='home')root.querySelector(s.book==='fraction'?'.fraction-book':'.pattern-book')?.classList.add('journey-hidden-book');
  const start=mode==='home'&&!s.final?(cameraFor(s.camera||0,s.book)||b):b,w=Math.min(width*.82,650),h=Math.min(height*.65,540),x=(width-w)/2,y=Math.max(18,(height-h-(bar?.offsetHeight||140)*.45)/2),t=s.lift??1;
  const px=start.x+(x-start.x)*t,py=start.y+(y-start.y)*t,sx=(start.w+(w-start.w)*t)/w,sy=(start.h+(h-start.h)*t)/h;
  flight.style.width=`${w}px`;flight.style.height=`${h}px`;flight.style.transform=`translate3d(${px}px,${py}px,0) scale(${sx},${sy}) rotate(${(1-t)*-4}deg)`;flight.style.opacity=String(s.fade===undefined?1:1-s.fade);flight.querySelector('.scroll-book-cover').style.transform=`rotateY(${-165*(s.open||0)}deg)`;
 }
 function panMission(s){let y=0;if(!s.mode.startsWith('fraction')&&!s.mode.startsWith('pattern'))return;const h=root.scrollHeight,min=Math.min(0,height-155-h),pos=selector=>{const e=root.querySelector(selector);return e?e.getBoundingClientRect().top-root.getBoundingClientRect().top:0;};
  const buildEnd=Math.max(0,pos('.bar-row.right')-(height-(bar?.offsetHeight||160))*.5);if(s.mode.endsWith('build'))y=-(s.pan||0)*buildEnd;
  else if(s.mode==='fraction-compare')y=-buildEnd+(height*.42-pos('.result')-70+buildEnd)*scrollEase(s.pan||0);
  else if(s.mode==='fraction-repair'){const from=Math.min(0,height*.2-pos('.repair-evidence')),to=Math.min(0,height*.45-pos('.replay'));y=from+(to-from)*(s.pan||0);}
  else if(s.mode==='pattern-compare')y=Math.min(0,height*.35-pos('.grove-loop'))-(s.pan||0)*150;
  else y=Math.min(0,height*.18-pos('.grove-layout'))-(s.pan||0)*Math.min(200,Math.max(0,h-height));
  root.style.transform=`translate3d(0,${Math.max(min,Math.min(0,y))}px,0)`;root.style.opacity=String(s.fade??1);
 }
 function paint(p){bar.hidden=scrollY>host.offsetTop+range+height*.35;const s=scrollScene(p);setMode(s.mode,p);if(chapter!==s.chapter){chapter=s.chapter;bar.querySelector('#scroll-tour-title').textContent=s.title;bar.querySelector('#scroll-tour-description').textContent=s.body;bar.querySelector('#scroll-tour-kicker').textContent=`SCROLL TO EXPLORE · ${chapter+1} / 10 · NO RESULTS SAVED`;document.querySelector('#announcement').textContent=s.title;bar.querySelector('[data-scroll-tour="start"]').textContent=s.mode.startsWith('pattern')?'Use Pattern Grove ↗':s.mode.startsWith('fraction')?'Use Fraction Foundry ↗':s.final?'Start my own mission ↗':'Start learning ↗';}
  if(s.mode==='home'){if(!bookBox)bookBox=measureBook(s.book||'fraction');cameraFor(s.camera||0,s.book||'fraction');const intro=root.querySelector('.nook-intro');if(intro)intro.style.opacity=String(noMotion()||s.final?1:1-scrollRange(p,0,.16)*.93);}
  panMission(s);paintBook(s);if(ghost){const blend=noMotion()?1:Math.min(1,.2+Math.max(0,(p-ghostAt)*ghostDir)/.018*.8);ghost.style.opacity=String(1-blend);root.style.opacity=String((s.fade??1)*blend);if(blend===1){ghost.remove();ghost=null;}}lastPaint=p;const input=bar.querySelector('#scroll-tour-position');if(document.activeElement!==input)input.value=String(Math.round(p*100));input.setAttribute('aria-valuetext',`${Math.round(p*100)} percent: ${s.title}`);bar.querySelector('[data-scroll-tour="previous"]').disabled=chapter===0;bar.querySelector('[data-scroll-tour="next"]').disabled=chapter===9;bar.style.setProperty('--scroll-progress',p);bar.classList.toggle('at-intro',p<.1);bar.classList.toggle('at-end',!!s.final);
 }
 function tick(time){raf=0;if(!mounted)return;const target=clampScroll((window.scrollY-host.offsetTop)/range),dt=Math.min(64,lastTime?time-lastTime:16);lastTime=time;if(noMotion()||Math.abs(target-progress)>.24)progress=target;else progress+=(target-progress)*(1-Math.exp(-dt/60));if(Math.abs(progress-target)<.0003)progress=target;paint(progress);if(progress!==target)raf=requestAnimationFrame(tick);}
 function request(){if(mounted&&!raf)raf=requestAnimationFrame(tick);}
 function seek(p,smooth=true){if(!mounted)return;window.scrollTo({top:host.offsetTop+clampScroll(p)*range,behavior:smooth&&!noMotion()?'smooth':'instant'});request();}
 function mount(explicit=false){if(mounted){if(explicit)seek(0);return;}if(blocked&&!explicit||!root.classList.contains('shelf-home'))return;blocked=false;mounted=true;mode='home';chapter=-1;progress=0;lastTime=0;lastPaint=0;
  let prefs;try{prefs=JSON.parse(window.fixiverseStorage.getItem('fixiverse-access-v1')||'{}');}catch{prefs={};}reduced=!!prefs.motion;anchor=document.createComment('Fixiverse app position');root.before(anchor);host=document.createElement('section');host.id='scroll-journey';host.setAttribute('aria-label','Scroll from the bookshelf into the learning missions');frame=document.createElement('div');frame.className='scroll-journey-stage';host.append(frame);anchor.after(host);frame.append(root);document.body.classList.add('scroll-journey-active');detachLanding();makeBar();measure();if(explicit)seek(0,false);request();
 }
 function end(render=true){if(!mounted)return;ghost?.remove();ghost=null;mounted=false;blocked=render;if(raf)cancelAnimationFrame(raf);raf=0;root.inert=false;root.style.removeProperty('transform');root.style.removeProperty('opacity');root.querySelectorAll('.journey-hidden-book').forEach(e=>e.classList.remove('journey-hidden-book'));if(originalStorage)window.fixiverseStorage=originalStorage;originalStorage=null;sandbox=false;window.fixiverseFraction?.endTour();window.fixiversePatternTour?.end();anchor.after(root);host.remove();bar.remove();anchor.remove();if(landing){landing.remove();if(root.classList.contains('shelf-home'))root.append(landing);}landingShell?.remove();landingShell=null;landing=null;host=frame=bar=flight=null;mode='';bookBox=null;bookID='';document.body.classList.remove('scroll-journey-active');if(render){window.fixiverseHome();document.querySelector('#screen-title')?.focus({preventScroll:true});}document.querySelector('#announcement').textContent='Scroll tour ended. Your saved work was kept.';}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-scroll-tour]');if(!b)return;const a=b.dataset.scrollTour;if(a==='exit'){end();return;}if(a==='start'){const mission=mode.startsWith('pattern')?'pattern':'fraction';end(false);window.fixiverseLaunch(mission);return;}if(a==='motion'){reduced=!reduced;b.textContent=noMotion()?'Motion off':'Reduce motion';b.setAttribute('aria-pressed',String(noMotion()));request();return;}seek(marks[Math.max(0,Math.min(9,chapter+(a==='next'?1:-1)))]);});
 document.addEventListener('input',e=>{if(e.target.id==='scroll-tour-position')seek(+e.target.value/100,false);});
 document.addEventListener('click',e=>{if(!mounted||!root.contains(e.target)&&!landingShell?.contains(e.target))return;const b=e.target.closest('button');if(!b)return;if(b.matches('[data-shelf="tour"]')){e.stopImmediatePropagation();seek(0);return;}if(b.matches('[data-shelf="primary"]')){e.stopImmediatePropagation();seek(.16);return;}if(b.matches('[data-shelf="book"][data-book="fraction"],[data-shelf="book"][data-book="pattern"]')&&progress<.98){e.stopImmediatePropagation();seek(b.dataset.book==='fraction'?.16:.69);return;}end(false);},true);
 motionQuery.addEventListener('change',()=>{if(bar){const b=bar.querySelector('[data-scroll-tour="motion"]');b.textContent=noMotion()?'Motion off':'Reduce motion';b.setAttribute('aria-pressed',String(noMotion()));}request();});window.addEventListener('scroll',request,{passive:true});window.addEventListener('resize',()=>{if(!mounted)return;const wasInside=scrollY>=host.offsetTop&&scrollY<=host.offsetTop+range,p=clampScroll((scrollY-host.offsetTop)/range);ghost?.remove();ghost=null;measure();if(wasInside)window.scrollTo({top:host.offsetTop+p*range,behavior:'instant'});request();});
 document.addEventListener('keydown',e=>{if(mounted&&e.key==='Escape'&&!document.querySelector('#dialog').open)end();});
 window.fixiverseTour={open:()=>mount(true),mount:()=>mount(false),active:()=>sandbox,scrolling:()=>mounted,end};
})();

